-- PREPARED, NOT RUN. Copilot + Otter verdict corrections (Elliot approved 24 Oct 2026). Frontend tools.json already carries these;
-- run this on D1 (with Elliot's Cloudflare login) so refresh-site.mjs doesn't revert them. Pinned with manual_override = 1.
SELECT 'before' AS snapshot, id, domain, compliance_status, trains_on_user_data, opt_out_available, summary, source_urls, manual_override, last_checked_at FROM tools WHERE domain IN ('github.com','otter.ai');
UPDATE tools SET compliance_status='compliant_with_caveats', trains_on_user_data=1, opt_out_available=1, summary='Rated on Copilot Free, Pro and Pro+: "from April 24 onward we will begin using interaction data—specifically inputs, outputs, code snippets, and associated context—from Copilot Free, Pro, and Pro+ users to train and improve our AI models unless you opt out." Opt out in settings under "Privacy". GitHub says "Copilot Business and Copilot Enterprise users are not affected by this update."', source_urls='["https://github.blog/changelog/2026-03-25-updates-to-our-privacy-statement-and-terms-of-service-how-we-use-your-data/", "https://github.blog/news-insights/company-news/updates-to-github-copilot-interaction-data-usage-policy/", "https://github.com/trust-center/privacy"]', manual_override=1, last_checked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE domain='github.com';
UPDATE tools SET compliance_status='compliant_with_caveats', trains_on_user_data=1, opt_out_available=1, summary='Privacy policy: "training our proprietary AI technology on de-identified audio recordings and on transcriptions (which may contain Personal Information)". Otter''s help centre gives an opt-out: Account Settings > Meetings > Feedback and Training, set Help improve Otter to "Don''t allow sharing", and "Otter will not access your conversation for training and product improvement." The policy doesn''t say whether this also covers de-identified training.', source_urls='["https://otter.ai/privacy-policy", "https://help.otter.ai/hc/en-us/articles/25352082563863-Provide-feedback-to-Otter"]', manual_override=1, last_checked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE domain='otter.ai';
SELECT compliance_status, COUNT(*) n FROM tools GROUP BY compliance_status;
